import { readFileSync } from "node:fs"
import { createRequire } from "node:module"
import { describe, expect, it } from "vitest"

// The deployed demo runs on MSW (D-011). public/mockServiceWorker.js is
// generated by `msw init` for one MSW version; after an upgrade it must be
// regenerated, or the worker and library disagree in production.

describe("public/mockServiceWorker.js", () => {
  it("matches the installed msw version", () => {
    const worker = readFileSync("public/mockServiceWorker.js", "utf8")
    const workerVersion = /const PACKAGE_VERSION = '([^']+)'/.exec(worker)?.[1]
    const require = createRequire(import.meta.url)
    const { version } = require("msw/package.json") as { version: string }
    expect(workerVersion).toBe(version)
  })
})
